        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        int pos = 0;
        int nums1Len = Integer.parseInt(lines.get(pos++).trim());
        int[] nums1 = new int[nums1Len];
        if (nums1Len > 0) {
            StringTokenizer st = new StringTokenizer(lines.get(pos));
            for (int i = 0; i < nums1Len; i++) nums1[i] = Integer.parseInt(st.nextToken());
        }
        pos++;
        int nums2Len = Integer.parseInt(lines.get(pos++).trim());
        int[] nums2 = new int[nums2Len];
        if (nums2Len > 0) {
            StringTokenizer st = new StringTokenizer(lines.get(pos));
            for (int i = 0; i < nums2Len; i++) nums2[i] = Integer.parseInt(st.nextToken());
        }
        pos++;
        int[] result = solve(nums1, nums2);
        System.out.println(Arrays.stream(result).mapToObj(String::valueOf).collect(Collectors.joining(" ")));
    }
}

